 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_6(uuid,uuid,text,text,jsonb)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false),makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)';END IF;
  
