CREATE FUNCTION pg_temp.legacy_bypass_predecessor_6(w uuid,i uuid,v text,producer text,sources jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 output knowledge_entries;source jsonb;current jsonb;output_source jsonb;derivation uuid;
BEGIN
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL OR current_setting('app.system_bypass',true)='true'
  OR NOT EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS NOT NULL AND current_setting('app.agent_workspace_id',true)::uuid<>w
  OR nullif(current_setting('app.agent_actor_id',true),'') IS NOT NULL AND current_setting('app.agent_actor_id',true)::uuid<>actor
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.knowledge_entries'::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 1000
  OR length(btrim(producer)) NOT BETWEEN 1 AND 256
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) proposed(value) WHERE proposed.value->>'resourceKind'='application_field') THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 SELECT k.* INTO output FROM knowledge_entries k WHERE k.workspace_id=w AND k.id=i AND k.scope_version::text=v
  AND k.xmin::text::bigint=(pg_current_xact_id()::text::numeric % 4294967296)::bigint FOR UPDATE;
 IF NOT FOUND OR output.created_by IS DISTINCT FROM actor OR output.scope_held OR output.source_id IS NOT NULL OR output.source_sha IS NOT NULL
  OR member_operation_scope_allows(w,output.sensitivity,output.compartments,true) IS NOT TRUE
  OR agent_mutation_scope_allows(output.compartments) IS NOT TRUE
  OR agent_read_scope_allows(output.sensitivity,output.compartments,output.project_ids) IS NOT TRUE THEN
  RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 output_source:=read_admitted_native_scope_snapshot(w,'knowledge_entry',i);
 IF output_source IS NULL OR output_source->>'held' IS DISTINCT FROM 'false' OR output_source->>'version' IS DISTINCT FROM v
  OR (SELECT count(DISTINCT (s->>'resourceKind',s->>'resourceId')) FROM jsonb_array_elements(sources) s)<>jsonb_array_length(sources) THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(sources) ORDER BY value->>'resourceKind',value->>'resourceId' LOOP
  IF entity_derivation_envelope_valid(source) IS NOT TRUE OR source->>'workspaceId' IS DISTINCT FROM w::text THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  IF source->>'resourceKind'='external_source' THEN
   IF external_source_retention_allowed(w,(source->>'resourceId')::uuid,source->>'version') IS NOT TRUE THEN
    RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   current:=external_source_snapshot(w,(source->>'resourceId')::uuid);
  ELSE current:=read_entity_derivation_source(w,source->>'resourceKind',(source->>'resourceId')::uuid);END IF;
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM source->>'version'
   OR current->>'validTo' IS NOT NULL OR current->>'retractedAt' IS NOT NULL
   OR (current->'workspaceId',current->'userId',current->'assistantId',current->'sensitivity')
    IS DISTINCT FROM (source->'workspaceId',source->'userId',source->'assistantId',source->'sensitivity')
   OR NOT (current->'compartments')@>(source->'compartments') OR NOT (source->'compartments')@>(current->'compartments')
   OR NOT (current->'projectIds')@>(source->'projectIds') OR NOT (source->'projectIds')@>(current->'projectIds') THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  IF source->>'userId' IS NOT NULL AND source->>'userId' IS DISTINCT FROM actor::text
   OR sensitivity_rank(source->>'sensitivity')>sensitivity_rank(output.sensitivity)
   OR NOT to_jsonb(output.compartments)@>(source->'compartments') OR NOT to_jsonb(output.project_ids)@>(source->'projectIds') THEN
   RAISE EXCEPTION 'scope_visibility_incompatible' USING ERRCODE='22023';END IF;
 END LOOP;
 INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;
 INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'knowledge_entry',i,v,producer,NULL,NULL,output.sensitivity,output.compartments,output.project_ids,p.revision
  FROM workspace_access_policies p WHERE p.workspace_id=w RETURNING id INTO derivation;
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT w,derivation,s->>'resourceKind',(s->>'resourceId')::uuid,s->>'version' FROM jsonb_array_elements(sources) s ORDER BY s->>'resourceKind',s->>'resourceId';
 SET CONSTRAINTS page_derivation_dependencies IMMEDIATE;
 SET CONSTRAINTS page_derivation_dependencies DEFERRED;
 RETURN derivation;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_predecessor_6(uuid,uuid,text,text,jsonb)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false),makeaclitem(owner_role,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)';END IF;
  IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid<>actual.oid AND p.pronamespace<>pg_my_temp_schema()
   AND (strpos(p.prosrc,'d3a9f9ce6e8ba66e32dd70054e72eda74ab1c08ca765b5e01dbe5cf3edc7a81e')>0 OR strpos(p.prosrc,md5(actual.prosrc))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(to_jsonb(actual)::text,'UTF8')),'hex'))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(ROW(actual.oid,actual.proname,actual.pronamespace,actual.proowner,actual.prolang,actual.procost,actual.prorows,actual.provariadic,actual.prosupport,actual.prokind,actual.prosecdef,actual.proleakproof,actual.proisstrict,actual.proretset,actual.provolatile,actual.proparallel,actual.pronargs,actual.pronargdefaults,actual.prorettype,actual.proargtypes,actual.proallargtypes,actual.proargmodes,actual.proargnames,actual.proargdefaults::text,actual.protrftypes,actual.prosrc,actual.probin,actual.prosqlbody::text,actual.proconfig,actual.proacl)::public.native_executable_contract_v1::text,'UTF8')),'hex'))>0))
   OR EXISTS(SELECT 1 FROM public.native_turn_contract_helpers WHERE signature='record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)')
   OR EXISTS(SELECT 1 FROM public.native_retained_contract_helpers WHERE signature='record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)')
  THEN RAISE EXCEPTION 'legacy_bypass_unreviewed_function_pin: %','record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)';END IF;
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_predecessor_6(uuid,uuid,text,text,jsonb);

CREATE FUNCTION pg_temp.legacy_bypass_predecessor_7(w uuid,i uuid,expected_version text,body text,producer text,sources jsonb,teams text[],projects uuid[])
RETURNS SETOF knowledge_entries LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;output knowledge_entries;
 context jsonb;mask jsonb;source jsonb;current jsonb;derivation uuid;prior_revision uuid;next_revision uuid;
BEGIN
 IF actor IS NULL OR body IS NULL OR expected_version IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL OR current_setting('app.system_bypass',true)='true'
  OR NOT EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS DISTINCT FROM w::text
  OR nullif(current_setting('app.agent_actor_id',true),'') IS DISTINCT FROM actor::text
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.knowledge_entries'::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 1000
  OR length(btrim(producer)) NOT BETWEEN 1 AND 256 OR teams IS NULL OR projects IS NULL
  OR array_position(teams,NULL) IS NOT NULL OR array_position(projects,NULL) IS NOT NULL
  OR (SELECT count(DISTINCT (s->>'resourceKind',s->>'resourceId')) FROM jsonb_array_elements(sources) s)<>jsonb_array_length(sources) THEN
  RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 context:=application_knowledge_query_context(w);IF context IS NULL THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 IF native_knowledge_version_fields_allowed(w,i,application_knowledge_field_keys()) IS NOT TRUE THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 SELECT k.* INTO output FROM knowledge_entries k WHERE k.workspace_id=w AND k.id=i AND k.scope_version::text=expected_version FOR UPDATE;
 IF NOT FOUND OR output.scope_held OR output.source_id IS NOT NULL OR output.source_sha IS NOT NULL
  OR member_operation_scope_allows(w,output.sensitivity,output.compartments,true) IS NOT TRUE
  OR agent_mutation_scope_allows(output.compartments) IS NOT TRUE
  OR agent_read_scope_allows(output.sensitivity,output.compartments,output.project_ids) IS NOT TRUE
  OR application_canonical_ancestry_allowed(w,'knowledge_entry',i,expected_version,true) IS NOT TRUE THEN
  RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
  mask:=read_native_application_field_catalog(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry');
  IF mask IS NULL OR NOT coalesce(mask->'writeFields' ? 'content',false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
  mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',i::text,expected_version);
  IF mask IS NULL OR NOT coalesce(mask->'writeFields' ? 'content',false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 END IF;
 SELECT ARRAY(SELECT DISTINCT unnest(output.compartments||teams) ORDER BY 1),ARRAY(SELECT DISTINCT unnest(output.project_ids||projects) ORDER BY 1)
  INTO output.compartments,output.project_ids;
 IF member_operation_scope_allows(w,output.sensitivity,output.compartments,true) IS NOT TRUE
  OR agent_mutation_scope_allows(output.compartments) IS NOT TRUE
  OR agent_read_scope_allows(output.sensitivity,output.compartments,output.project_ids) IS NOT TRUE THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 -- Every exact original observation is validated before its own canonical body changes.
 -- No source edge, selected field or same-destination guard is removed.
 FOR source IN SELECT value FROM jsonb_array_elements(sources) ORDER BY value->>'resourceKind',value->>'resourceId' LOOP
  IF entity_derivation_envelope_valid(source) IS NOT TRUE OR source->>'workspaceId' IS DISTINCT FROM w::text THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  IF source->>'resourceKind'='external_source' THEN
   IF external_source_retention_allowed(w,(source->>'resourceId')::uuid,source->>'version') IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   current:=external_source_snapshot(w,(source->>'resourceId')::uuid);
  ELSE current:=read_entity_derivation_source(w,source->>'resourceKind',(source->>'resourceId')::uuid);END IF;
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM source->>'version'
   OR current->>'validTo' IS NOT NULL OR current->>'retractedAt' IS NOT NULL
   OR (current->'workspaceId',current->'userId',current->'assistantId',current->'sensitivity') IS DISTINCT FROM (source->'workspaceId',source->'userId',source->'assistantId',source->'sensitivity')
   OR NOT (current->'compartments')@>(source->'compartments') OR NOT (source->'compartments')@>(current->'compartments')
   OR NOT (current->'projectIds')@>(source->'projectIds') OR NOT (source->'projectIds')@>(current->'projectIds') THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  IF source->>'userId' IS NOT NULL AND source->>'userId' IS DISTINCT FROM actor::text OR sensitivity_rank(source->>'sensitivity')>sensitivity_rank(output.sensitivity)
   OR NOT to_jsonb(output.compartments)@>(source->'compartments') OR NOT to_jsonb(output.project_ids)@>(source->'projectIds') THEN RAISE EXCEPTION 'scope_visibility_incompatible' USING ERRCODE='22023';END IF;
 END LOOP;
 prior_revision:=capture_native_knowledge_version(w,i,expected_version,application_knowledge_field_keys());
 PERFORM archive_native_knowledge_version(w,i,expected_version,prior_revision);
 INSERT INTO knowledge_entry_scope_revisions(workspace_id,entry_id,sensitivity,compartments,project_ids,revision_kind)
  VALUES(w,i,output.sensitivity,output.compartments,output.project_ids,'body') RETURNING id INTO next_revision;
 INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;
 INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'knowledge_entry_revision',next_revision,'1',producer,NULL,NULL,output.sensitivity,output.compartments,output.project_ids,p.revision
  FROM workspace_access_policies p WHERE p.workspace_id=w RETURNING id INTO derivation;
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT w,derivation,s->>'resourceKind',(s->>'resourceId')::uuid,s->>'version' FROM jsonb_array_elements(sources) s ORDER BY s->>'resourceKind',s->>'resourceId';
 -- Validate the complete original input graph before its carrier is changed.
 -- New publication/value pairing remains deferred until the actual result exists.
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies IMMEDIATE;
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies DEFERRED;
 UPDATE knowledge_entries k SET content=body,compartments=output.compartments,project_ids=output.project_ids,updated_at=now()
  WHERE k.workspace_id=w AND k.id=i AND k.scope_version::text=expected_version RETURNING k.* INTO output;
 IF NOT FOUND THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
  mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',i::text,output.scope_version::text);
  IF mask IS NULL OR NOT coalesce(mask->'writeFields' ? 'content',false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 END IF;
 PERFORM publish_native_knowledge_body_revision(w,i,output.scope_version::text,next_revision);
 RETURN NEXT output;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[])');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_predecessor_7(uuid,uuid,text,text,text,jsonb,text[],uuid[])');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false),makeaclitem(owner_role,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[])';END IF;
  IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid<>actual.oid AND p.pronamespace<>pg_my_temp_schema()
   AND (strpos(p.prosrc,'1c98257346b82f551627d48639f4dee1ce41ce143c88347ee87d33dfbbcf2e2e')>0 OR strpos(p.prosrc,md5(actual.prosrc))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(to_jsonb(actual)::text,'UTF8')),'hex'))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(ROW(actual.oid,actual.proname,actual.pronamespace,actual.proowner,actual.prolang,actual.procost,actual.prorows,actual.provariadic,actual.prosupport,actual.prokind,actual.prosecdef,actual.proleakproof,actual.proisstrict,actual.proretset,actual.provolatile,actual.proparallel,actual.pronargs,actual.pronargdefaults,actual.prorettype,actual.proargtypes,actual.proallargtypes,actual.proargmodes,actual.proargnames,actual.proargdefaults::text,actual.protrftypes,actual.prosrc,actual.probin,actual.prosqlbody::text,actual.proconfig,actual.proacl)::public.native_executable_contract_v1::text,'UTF8')),'hex'))>0))
   OR EXISTS(SELECT 1 FROM public.native_turn_contract_helpers WHERE signature='update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[])')
   OR EXISTS(SELECT 1 FROM public.native_retained_contract_helpers WHERE signature='update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[])')
  THEN RAISE EXCEPTION 'legacy_bypass_unreviewed_function_pin: %','update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[])';END IF;
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_predecessor_7(uuid,uuid,text,text,text,jsonb,text[],uuid[]);
$ordinary_acl_historic$;

 -- Lock only the three tables whose six existing policies consume the old OIDs.
 LOCK TABLE public.crm_activities,public.workspace_compartments,public.workspace_groups IN ACCESS EXCLUSIVE MODE;
 FOR item IN SELECT * FROM (VALUES
   (old_routines[1],'public.workspace_groups'::regclass,'workspace_groups_directory','r','can_view_department_directory(workspace_id, id)',NULL),
   (old_routines[1],'public.workspace_compartments'::regclass,'workspace_compartments_directory','r','((managed_by IS DISTINCT FROM ''team''::text) OR can_view_department_directory(workspace_id, managed_ref_id))',NULL),
   (old_routines[2],'public.crm_activities'::regclass,'crm_activities_scope_read','r','crm_activity_scope_allows(crm_activities.*, false)',NULL),
   (old_routines[2],'public.crm_activities'::regclass,'crm_activities_scope_insert','a',NULL,'crm_activity_scope_allows(crm_activities.*, true)'),
   (old_routines[2],'public.crm_activities'::regclass,'crm_activities_scope_update','w','crm_activity_scope_allows(crm_activities.*, true)','crm_activity_scope_allows(crm_activities.*, true)'),
   (old_routines[2],'public.crm_activities'::regclass,'crm_activities_scope_delete','d','crm_activity_scope_allows(crm_activities.*, true)',NULL)
 ) AS reviewed(fn,relation,name,command,using_expr,check_expr) LOOP
  SELECT * INTO STRICT relation FROM pg_class WHERE oid=item.relation;
  SELECT * INTO policy FROM pg_policy WHERE polrelid=relation.oid AND polname=item.name;
  IF NOT relation.relrowsecurity OR relation.relforcerowsecurity OR relation.relowner<>owner_role
   OR policy.oid IS NULL OR policy.polpermissive OR policy.polcmd::text<>item.command OR policy.polroles<>ARRAY[0::oid]
   OR pg_get_expr(policy.polqual,relation.oid) IS DISTINCT FROM item.using_expr
   OR pg_get_expr(policy.polwithcheck,relation.oid) IS DISTINCT FROM item.check_expr
   OR (SELECT count(*) FROM pg_depend d WHERE d.classid='pg_policy'::regclass AND d.objid=policy.oid
      AND d.objsubid=0 AND d.refclassid='pg_proc'::regclass AND d.refobjid=item.fn AND d.refobjsubid=0 AND d.deptype='n')
      <> (item.using_expr IS NOT NULL)::integer + (item.check_expr IS NOT NULL)::integer
  THEN RAISE EXCEPTION 'legacy_ordinary_acl_policy_changed: %',item.name;END IF;
  saved_policies:=array_append(saved_policies,policy.oid);
 END LOOP;

 IF (SELECT count(*) FROM pg_depend d WHERE d.refclassid='pg_proc'::regclass AND d.refobjid=ANY(old_routines))<>7
 THEN RAISE EXCEPTION 'legacy_ordinary_acl_unreviewed_inbound_dependency';END IF;
 FOR item IN SELECT * FROM (VALUES
  (old_routines[1],'pg_language'::regclass::oid,(SELECT oid FROM pg_language WHERE lanname='plpgsql')),
  (old_routines[2],'pg_type'::regclass::oid,'public.crm_activities'::regtype::oid)
 ) AS reviewed(fn,dependency_class,dependency) LOOP
  routine:=item.fn;
  IF (SELECT count(*) FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=routine)<>2
   OR NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=routine AND d.objsubid=0
     AND d.refclassid='pg_namespace'::regclass AND d.refobjid='public'::regnamespace AND d.refobjsubid=0 AND d.deptype='n')
   OR NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=routine AND d.objsubid=0
     AND d.refclassid=item.dependency_class AND d.refobjid=item.dependency AND d.refobjsubid=0 AND d.deptype='n')
   OR (SELECT count(*) FROM pg_shdepend d WHERE d.dbid=(SELECT oid FROM pg_database WHERE datname=current_database())
        AND d.classid='pg_proc'::regclass AND d.objid=routine)<>2
   OR (SELECT count(*) FROM pg_shdepend d WHERE d.dbid=(SELECT oid FROM pg_database WHERE datname=current_database())
        AND d.classid='pg_proc'::regclass AND d.objid=routine AND d.objsubid=0 AND d.refclassid='pg_authid'::regclass
        AND ((d.refobjid=owner_role AND d.deptype='o') OR (d.refobjid=runtime_role AND d.deptype='a')))<>2
  THEN RAISE EXCEPTION 'legacy_ordinary_acl_outbound_dependency_changed: %',routine::regprocedure;END IF;
 END LOOP;

 IF (SELECT count(*) FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid
     WHERE c.relnamespace='public'::regnamespace AND c.relkind IN('r','p')
       AND a.attnum>0 AND NOT a.attisdropped AND a.atttypid='regprocedure'::regtype)<>4
 THEN RAISE EXCEPTION 'legacy_ordinary_acl_registry_shape_changed';END IF;
 FOR item IN SELECT * FROM (VALUES ('application_native_configuration_operations','apply_handler'),('application_native_field_contracts','catalog_reader'),('application_native_field_contracts','configuration_reader'),('application_native_field_contracts','metadata_reader')) AS reviewed(relation_name,column_name) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid
     WHERE c.oid=to_regclass('public.'||item.relation_name) AND a.attname=item.column_name
       AND a.attnum>0 AND NOT a.attisdropped AND a.atttypid='regprocedure'::regtype)
  THEN RAISE EXCEPTION 'legacy_ordinary_acl_registry_shape_changed';END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE %I::oid=ANY($1))',item.relation_name,item.column_name)
   INTO occupied USING old_routines;
  IF occupied THEN RAISE EXCEPTION 'legacy_ordinary_acl_registered_reference';END IF;
 END LOOP;

 -- Reorder only the previously authenticated, owner-issued app grants.
 REVOKE EXECUTE ON FUNCTION public.admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text), public.apply_knowledge_source_refresh(jsonb,jsonb), public.native_knowledge_creation_fields_allowed(uuid,text[],uuid,text), public.record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb), public.update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[]) FROM app_user;
 GRANT EXECUTE ON FUNCTION public.admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text), public.apply_knowledge_source_refresh(jsonb,jsonb), public.native_knowledge_creation_fields_allowed(uuid,text[],uuid,text), public.record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb), public.update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[]) TO app_user;

 -- No other session can observe the temporary deny predicates. Keep the
 -- policy OIDs so only their references to the two default-ACL routines change.
 ALTER POLICY workspace_groups_directory ON public.workspace_groups USING (false);
 ALTER POLICY workspace_compartments_directory ON public.workspace_compartments USING (false);
 ALTER POLICY crm_activities_scope_read ON public.crm_activities USING (false);
 ALTER POLICY crm_activities_scope_insert ON public.crm_activities WITH CHECK (false);
 ALTER POLICY crm_activities_scope_update ON public.crm_activities USING (false) WITH CHECK (false);
 ALTER POLICY crm_activities_scope_delete ON public.crm_activities USING (false);
 DROP FUNCTION public.can_view_department_directory(uuid,uuid), public.crm_activity_scope_allows(crm_activities,boolean) RESTRICT;
 CREATE FUNCTION public.can_view_department_directory(p_workspace_id uuid,p_team_id uuid) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE viewer uuid; reach text[];
BEGIN
  IF current_setting('app.system_bypass',true)='true' THEN RETURN true; END IF;
  viewer=nullif(current_setting('app.current_user_id',true),'')::uuid;
  IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=p_workspace_id AND user_id=viewer) THEN RETURN false; END IF;
  -- INSERT ... RETURNING evaluates SELECT policies before the inserted group
  -- is query-visible to a STABLE helper. Administrative authority is independent
  -- of group visibility and must not query the not-yet-visible group row.
  IF EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=p_workspace_id AND user_id=viewer AND role IN ('owner','admin')) THEN RETURN true; END IF;
  reach=effective_member_read_compartments(viewer,p_workspace_id);
  RETURN EXISTS(SELECT 1 FROM workspace_groups g WHERE g.id=p_team_id AND g.workspace_id=p_workspace_id AND (
    g.kind<>'team' OR g.directory_visibility='workspace' OR reach IS NULL OR g.compartment_key=ANY(reach)
    OR EXISTS(SELECT 1 FROM workspace_team_managers m WHERE m.workspace_id=p_workspace_id AND m.team_id=p_team_id AND m.user_id=viewer AND m.revoked_at IS NULL)
  ));
END;
$$;
 CREATE FUNCTION public.crm_activity_scope_allows(a crm_activities,mutation boolean) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
  SELECT NOT a.scope_held
    AND (a.scope_origin='captured' OR NOT EXISTS(SELECT 1 FROM workspace_access_policies p
      WHERE p.workspace_id=a.workspace_id AND p.classification_mode='strict'))
    AND CASE WHEN current_setting('app.system_bypass',true)='true' THEN true ELSE EXISTS(
      SELECT 1 FROM entities e JOIN workspaces w ON w.id=e.workspace_id JOIN workspace_members m ON m.workspace_id=e.workspace_id
        AND m.user_id=nullif(current_setting('app.current_user_id',true),'')::uuid
      WHERE e.id=a.entity_id AND e.workspace_id=a.workspace_id
        AND e.kind IN('person','company','deal') AND e.valid_to IS NULL AND e.retracted_at IS NULL AND NOT e.scope_held
        AND (a.user_id IS NULL OR a.user_id=m.user_id) AND (e.user_id IS NULL OR e.user_id=m.user_id)
        AND CASE WHEN w.department_read_v2 THEN
          department_read_grants() ? a.workspace_id::text
          AND department_row_allows(department_read_grants(),a.workspace_id,a.sensitivity,a.compartments,a.user_id)
          AND department_row_allows(department_read_grants(),e.workspace_id,e.sensitivity,e.compartments,e.user_id)
        ELSE (sensitivity_rank(a.sensitivity)<=sensitivity_rank(m.clearance)
        AND sensitivity_rank(e.sensitivity)<=sensitivity_rank(m.clearance)
        AND (effective_member_team_compartments(m.user_id,m.workspace_id) IS NULL OR
          (a.compartments <@ effective_member_team_compartments(m.user_id,m.workspace_id)
            AND e.compartments <@ effective_member_team_compartments(m.user_id,m.workspace_id)))
        AND context_scope_allows_current_principal(a.workspace_id,a.sensitivity,a.compartments,a.project_ids)
        AND context_scope_allows_current_principal(e.workspace_id,e.sensitivity,e.compartments,e.project_ids)) END
        AND agent_visibility_allows(a.workspace_id,a.user_id,a.assistant_id)
        AND agent_visibility_allows(e.workspace_id,e.user_id,e.assistant_id)
        AND (NOT mutation OR (agent_mutation_scope_allows(a.compartments) AND agent_mutation_scope_allows(e.compartments)))
    ) END
$$;
 ALTER POLICY workspace_groups_directory ON public.workspace_groups USING (can_view_department_directory(workspace_id, id));
 ALTER POLICY workspace_compartments_directory ON public.workspace_compartments USING (((managed_by IS DISTINCT FROM 'team'::text) OR can_view_department_directory(workspace_id, managed_ref_id)));
 ALTER POLICY crm_activities_scope_read ON public.crm_activities USING (crm_activity_scope_allows(crm_activities.*, false));
 ALTER POLICY crm_activities_scope_insert ON public.crm_activities WITH CHECK (crm_activity_scope_allows(crm_activities.*, true));
 ALTER POLICY crm_activities_scope_update ON public.crm_activities USING (crm_activity_scope_allows(crm_activities.*, true)) WITH CHECK (crm_activity_scope_allows(crm_activities.*, true));
 ALTER POLICY crm_activities_scope_delete ON public.crm_activities USING (crm_activity_scope_allows(crm_activities.*, true));
 FOR item IN SELECT * FROM (VALUES
   (old_routines[1],'public.workspace_groups'::regclass,'workspace_groups_directory','r','can_view_department_directory(workspace_id, id)',NULL),
   (old_routines[1],'public.workspace_compartments'::regclass,'workspace_compartments_directory','r','((managed_by IS DISTINCT FROM ''team''::text) OR can_view_department_directory(workspace_id, managed_ref_id))',NULL),
   (old_routines[2],'public.crm_activities'::regclass,'crm_activities_scope_read','r','crm_activity_scope_allows(crm_activities.*, false)',NULL),
   (old_routines[2],'public.crm_activities'::regclass,'crm_activities_scope_insert','a',NULL,'crm_activity_scope_allows(crm_activities.*, true)'),
   (old_routines[2],'public.crm_activities'::regclass,'crm_activities_scope_update','w','crm_activity_scope_allows(crm_activities.*, true)','crm_activity_scope_allows(crm_activities.*, true)'),
   (old_routines[2],'public.crm_activities'::regclass,'crm_activities_scope_delete','d','crm_activity_scope_allows(crm_activities.*, true)',NULL)
 ) AS reviewed(old_fn,relation,name,command,using_expr,check_expr) LOOP
  SELECT * INTO STRICT relation FROM pg_class WHERE oid=item.relation;
  SELECT * INTO STRICT policy FROM pg_policy WHERE polrelid=relation.oid AND polname=item.name;
  routine:=CASE WHEN item.old_fn=old_routines[1] THEN 'public.can_view_department_directory(uuid,uuid)'::regprocedure::oid
                ELSE 'public.crm_activity_scope_allows(crm_activities,boolean)'::regprocedure::oid END;
  IF NOT relation.relrowsecurity OR relation.relforcerowsecurity OR relation.relowner<>owner_role
   OR policy.polpermissive OR policy.polcmd::text<>item.command OR policy.polroles<>ARRAY[0::oid]
   OR pg_get_expr(policy.polqual,relation.oid) IS DISTINCT FROM item.using_expr
   OR pg_get_expr(policy.polwithcheck,relation.oid) IS DISTINCT FROM item.check_expr
   OR (SELECT count(*) FROM pg_depend d WHERE d.classid='pg_policy'::regclass AND d.objid=policy.oid
      AND d.objsubid=0 AND d.refclassid='pg_proc'::regclass AND d.refobjid=routine AND d.refobjsubid=0 AND d.deptype='n')
      <> (item.using_expr IS NOT NULL)::integer + (item.check_expr IS NOT NULL)::integer
  THEN RAISE EXCEPTION 'legacy_ordinary_acl_rebind_changed: %',item.name;END IF;
  checked_policies:=array_append(checked_policies,policy.oid);
 END LOOP;
 IF checked_policies IS DISTINCT FROM saved_policies
 THEN RAISE EXCEPTION 'legacy_ordinary_acl_policy_identity_changed';END IF;

 EXECUTE $ordinary_acl_repaired$
CREATE FUNCTION pg_temp.legacy_bypass_predecessor_0(p jsonb,e jsonb,sources jsonb,target_id uuid,expected_version text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 w uuid:=(p->>'workspaceId')::uuid;s workspace_knowledge_sources;old knowledge_entries;
 context jsonb;catalog jsonb;mask jsonb;fields text[];source jsonb;current jsonb;field text;
BEGIN
 IF actor IS NULL OR actor::text IS DISTINCT FROM p->>'actorId'
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL OR current_setting('app.system_bypass',true)='true'
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS DISTINCT FROM w::text
  OR nullif(current_setting('app.agent_actor_id',true),'') IS DISTINCT FROM actor::text
  OR NOT EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.knowledge_entries'::regclass
    WHERE r.rolname=session_user AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 1000
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) x WHERE x->>'resourceKind'='application_field')
  OR entity_derivation_envelope_valid(p||jsonb_build_object('userId',NULL,'assistantId',NULL)) IS NOT TRUE
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='42501';END IF;
 SELECT * INTO s FROM workspace_knowledge_sources WHERE workspace_id=w AND id=(p->>'sourceId')::uuid FOR SHARE;
 IF s.id IS NULL OR s.binding_held OR s.configured_by_user_id IS NULL
  OR s.id::text IS DISTINCT FROM e->>'id' OR s.workspace_id::text IS DISTINCT FROM e->>'workspaceId'
  OR s.binding_version::text IS DISTINCT FROM e->>'bindingVersion'
  OR s.repo IS DISTINCT FROM e->>'repo' OR s.branch IS DISTINCT FROM e->>'branch'
  OR s.root_path IS DISTINCT FROM e->>'rootPath' OR s.source_type IS DISTINCT FROM e->>'sourceType'
  OR s.connector_instance_id::text IS DISTINCT FROM e->>'connectorInstanceId'
  OR(s.source_type='github' AND s.write_access IS DISTINCT FROM true)
  OR(s.sync_run_id IS NOT NULL AND s.sync_lease_until>clock_timestamp())
  THEN RAISE EXCEPTION 'knowledge_source_changed' USING ERRCODE='42501';END IF;
 IF member_operation_scope_allows(w,s.binding_sensitivity,s.binding_compartments,true) IS NOT TRUE
  OR agent_mutation_scope_allows(s.binding_compartments) IS NOT TRUE
  OR agent_read_scope_allows(s.binding_sensitivity,s.binding_compartments,s.binding_project_ids) IS NOT TRUE
  OR read_entity_derivation_source(w,'knowledge_source',s.id) IS NULL
  OR sensitivity_rank(p->>'sensitivity')<sensitivity_rank(s.binding_sensitivity)
  OR NOT(p->'compartments')@>to_jsonb(s.binding_compartments) OR NOT(p->'projectIds')@>to_jsonb(s.binding_project_ids)
  THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM knowledge_entries WHERE workspace_id=w AND path=p->>'path' FOR UPDATE;
 IF target_id IS NULL THEN
  IF old.id IS NOT NULL OR expected_version IS NOT NULL THEN RAISE EXCEPTION 'knowledge_source_target_conflict';END IF;
  fields:=ARRAY['path','title','content','summary','tags','metadata'];
  IF native_knowledge_creation_fields_allowed(w,fields,NULL,NULL) IS NOT TRUE THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 ELSE
  IF old.id IS DISTINCT FROM target_id OR old.source_id IS DISTINCT FROM s.id OR old.scope_held
   OR old.scope_version::text IS DISTINCT FROM expected_version
   OR native_knowledge_version_fields_allowed(w,old.id,application_knowledge_field_keys()) IS NOT TRUE
   OR application_canonical_ancestry_allowed(w,'knowledge_entry',old.id,expected_version,true) IS NOT TRUE
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) x WHERE x->>'resourceKind'='knowledge_entry'
     AND x->>'resourceId'=old.id::text AND x->>'version'=expected_version)
   THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  fields:=ARRAY['content'];
  IF old.title IS DISTINCT FROM p->>'title' THEN fields:=array_append(fields,'title');END IF;
  IF old.summary IS DISTINCT FROM p->>'summary' THEN fields:=array_append(fields,'summary');END IF;
  IF to_jsonb(old.tags) IS DISTINCT FROM p->'tags' THEN fields:=array_append(fields,'tags');END IF;
  IF old.metadata IS DISTINCT FROM p->'metadata' THEN fields:=array_append(fields,'metadata');END IF;
  context:=application_knowledge_query_context(w);
  IF context IS NULL THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
  IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
   catalog:=read_native_application_field_catalog(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry');
   mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',old.id::text,expected_version);
   FOREACH field IN ARRAY fields LOOP
    IF catalog IS NULL OR mask IS NULL OR NOT coalesce(catalog->'writeFields' ? field,false)
     OR NOT coalesce(mask->'writeFields' ? field,false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
   END LOOP;
  END IF;
 END IF;
 IF member_operation_scope_allows(w,p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),true) IS NOT TRUE
  OR agent_mutation_scope_allows(ARRAY(SELECT jsonb_array_elements_text(p->'compartments'))) IS NOT TRUE
  OR agent_read_scope_allows(p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid)) IS NOT TRUE
  THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(sources) LOOP
  IF entity_derivation_envelope_valid(source) IS NOT TRUE OR source->>'workspaceId' IS DISTINCT FROM w::text THEN RAISE EXCEPTION 'scope_evidence_missing';END IF;
  IF source->>'resourceKind'='external_source' THEN
   IF external_source_retention_allowed(w,(source->>'resourceId')::uuid,source->>'version') IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed';END IF;
   current:=external_source_snapshot(w,(source->>'resourceId')::uuid);
  ELSE current:=read_entity_derivation_source(w,source->>'resourceKind',(source->>'resourceId')::uuid);END IF;
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM source->>'version'
   OR current->>'validTo' IS NOT NULL OR current->>'retractedAt' IS NOT NULL
   OR(current->'workspaceId',current->'userId',current->'assistantId',current->'sensitivity') IS DISTINCT FROM(source->'workspaceId',source->'userId',source->'assistantId',source->'sensitivity')
   OR NOT(current->'compartments')@>(source->'compartments') OR NOT(source->'compartments')@>(current->'compartments')
   OR NOT(current->'projectIds')@>(source->'projectIds') OR NOT(source->'projectIds')@>(current->'projectIds') THEN RAISE EXCEPTION 'scope_source_changed';END IF;
  IF source->>'userId' IS NOT NULL AND source->>'userId' IS DISTINCT FROM actor::text
   OR sensitivity_rank(source->>'sensitivity')>sensitivity_rank(p->>'sensitivity')
   OR NOT(p->'compartments')@>(source->'compartments') OR NOT(p->'projectIds')@>(source->'projectIds') THEN RAISE EXCEPTION 'scope_visibility_incompatible';END IF;
 END LOOP;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_predecessor_0(jsonb,jsonb,jsonb,uuid,text)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false),makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text)';END IF;
  IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid<>actual.oid AND p.pronamespace<>pg_my_temp_schema()
   AND (strpos(p.prosrc,'b4855c0f70a23ecc416ff39f3b6710c70962a2b74648851339e0b4d3d1698913')>0 OR strpos(p.prosrc,md5(actual.prosrc))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(to_jsonb(actual)::text,'UTF8')),'hex'))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(ROW(actual.oid,actual.proname,actual.pronamespace,actual.proowner,actual.prolang,actual.procost,actual.prorows,actual.provariadic,actual.prosupport,actual.prokind,actual.prosecdef,actual.proleakproof,actual.proisstrict,actual.proretset,actual.provolatile,actual.proparallel,actual.pronargs,actual.pronargdefaults,actual.prorettype,actual.proargtypes,actual.proallargtypes,actual.proargmodes,actual.proargnames,actual.proargdefaults::text,actual.protrftypes,actual.prosrc,actual.probin,actual.prosqlbody::text,actual.proconfig,actual.proacl)::public.native_executable_contract_v1::text,'UTF8')),'hex'))>0))
   OR EXISTS(SELECT 1 FROM public.native_turn_contract_helpers WHERE signature='admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text)')
   OR EXISTS(SELECT 1 FROM public.native_retained_contract_helpers WHERE signature='admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text)')
  THEN RAISE EXCEPTION 'legacy_bypass_unreviewed_function_pin: %','admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text)';END IF;
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_predecessor_0(jsonb,jsonb,jsonb,uuid,text);
CREATE FUNCTION pg_temp.legacy_bypass_predecessor_1(w uuid,administrator uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE revision text;context jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.tasks'::regclass
   WHERE r.rolname=session_user AND r.oid=c.relowner)
  OR nullif(current_setting('app.scope_review_actor',true),'') IS DISTINCT FROM administrator::text
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.current_user_id',true),'') IS NOT NULL AND current_setting('app.current_user_id',true)<>administrator::text THEN
  RAISE EXCEPTION 'access_unavailable: native review identity unavailable' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=administrator AND m.role IN('owner','admin') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'access_unavailable: current administrator required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM application_native_role_assignments r WHERE r.workspace_id=w AND r.module_key='native' AND r.status='active' ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM application_policy_workspace_epochs e WHERE e.workspace_id=w)
  OR NOT EXISTS(SELECT 1 FROM application_policy_contract_epoch) THEN
  RAISE EXCEPTION 'access_unavailable: native review epoch missing' USING ERRCODE='42501';END IF;
 revision:=application_native_task_write_policy_revision(w);
 IF revision IS NULL THEN RAISE EXCEPTION 'access_unavailable: native review policy unavailable' USING ERRCODE='42501';END IF;
 SELECT jsonb_object_agg(name,to_jsonb(nullif(current_setting(name,true),''))) INTO context FROM unnest(ARRAY[
  'app.current_user_id','app.application_id','app.application_assistant_id','app.v2_assistant_id','app.application_command_key',
  'app.agent_workspace_id','app.agent_actor_id','app.agent_assistant_id','app.scope_review_actor','app.system_bypass',
  'app.agent_clearance','app.agent_compartments','app.agent_project_ids','app.agent_shared_audience','app.agent_mutation_compartments',
  'app.agent_visibility_assistants','app.v2_active','app.v2_context_department','app.v2_binding','app.v2_cap','app.native_task_write_intent']) name;
 RETURN jsonb_build_object('session',session_user,'contextDigest',application_field_digest(context),'policy',revision);
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.application_native_task_review_current(uuid,uuid)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_predecessor_1(uuid,uuid)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','application_native_task_review_current(uuid,uuid)';END IF;
  IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid<>actual.oid AND p.pronamespace<>pg_my_temp_schema()
   AND (strpos(p.prosrc,'df575f7a46b8a7d7fc6ddeb9ba376762a3ee0e71c3f41dcefc9be31e4381ce33')>0 OR strpos(p.prosrc,md5(actual.prosrc))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(to_jsonb(actual)::text,'UTF8')),'hex'))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(ROW(actual.oid,actual.proname,actual.pronamespace,actual.proowner,actual.prolang,actual.procost,actual.prorows,actual.provariadic,actual.prosupport,actual.prokind,actual.prosecdef,actual.proleakproof,actual.proisstrict,actual.proretset,actual.provolatile,actual.proparallel,actual.pronargs,actual.pronargdefaults,actual.prorettype,actual.proargtypes,actual.proallargtypes,actual.proargmodes,actual.proargnames,actual.proargdefaults::text,actual.protrftypes,actual.prosrc,actual.probin,actual.prosqlbody::text,actual.proconfig,actual.proacl)::public.native_executable_contract_v1::text,'UTF8')),'hex'))>0))
   OR EXISTS(SELECT 1 FROM public.native_turn_contract_helpers WHERE signature='application_native_task_review_current(uuid,uuid)')
   OR EXISTS(SELECT 1 FROM public.native_retained_contract_helpers WHERE signature='application_native_task_review_current(uuid,uuid)')
  THEN RAISE EXCEPTION 'legacy_bypass_unreviewed_function_pin: %','application_native_task_review_current(uuid,uuid)';END IF;
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_predecessor_1(uuid,uuid);
CREATE FUNCTION pg_temp.legacy_bypass_predecessor_2(p jsonb,e jsonb) RETURNS SETOF knowledge_entries
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE w uuid:=(p->>'workspaceId')::uuid;s workspace_knowledge_sources;old knowledge_entries;output knowledge_entries;
 actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 prior_revision uuid;next_revision uuid;derivation uuid;context jsonb;catalog jsonb;mask jsonb;field text;fields text[];
 setting record;saved jsonb:='{}';node record;current jsonb;
BEGIN
 PERFORM assert_bound_knowledge_sync_actor(w,(p->>'sourceId')::uuid);
 SELECT * INTO s FROM workspace_knowledge_sources WHERE workspace_id=w AND id=(p->>'sourceId')::uuid FOR SHARE;
 IF s.id IS NULL OR s.binding_held OR s.sync_run_id IS NULL OR s.sync_lease_until IS NULL OR s.sync_run_id::text IS DISTINCT FROM e->>'syncRunId'
  OR s.sync_lease_until<=clock_timestamp() OR s.binding_version::text IS DISTINCT FROM e->>'bindingVersion'
  OR s.id::text IS DISTINCT FROM e->>'id' OR w::text IS DISTINCT FROM e->>'workspaceId'
  OR s.repo IS DISTINCT FROM e->>'repo' OR s.branch IS DISTINCT FROM e->>'branch' OR s.root_path IS DISTINCT FROM e->>'rootPath'
  OR s.source_type IS DISTINCT FROM e->>'sourceType' OR s.connector_instance_id::text IS DISTINCT FROM e->>'connectorInstanceId'
  OR s.last_synced_sha IS DISTINCT FROM e->>'lastSyncedSha' OR s.configured_by_user_id::text IS DISTINCT FROM e->>'configuredByUserId'
  OR s.binding_sensitivity IS DISTINCT FROM e->>'bindingSensitivity'
  OR to_jsonb(s.binding_compartments) IS DISTINCT FROM e->'bindingCompartments'
  OR to_jsonb(s.binding_project_ids) IS DISTINCT FROM e->'bindingProjectIds'
  THEN RAISE EXCEPTION 'knowledge_source_changed' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM knowledge_entries WHERE workspace_id=w AND path=p->>'path' FOR UPDATE;
 IF old.id IS NULL OR NOT EXISTS(SELECT 1 FROM knowledge_repo_publication_heads h WHERE h.workspace_id=w AND h.entry_id=old.id)
  OR coalesce(p->>'operation','') NOT IN('','related') THEN
  RETURN QUERY SELECT * FROM apply_knowledge_source_sync(p,e);RETURN;
 END IF;
 IF old.source_id IS DISTINCT FROM s.id OR old.scope_held OR coalesce(p->>'sourceSha','')=''
  OR entity_derivation_envelope_valid(p||jsonb_build_object('userId',NULL,'assistantId',NULL)) IS NOT TRUE
  OR p->>'userId' IS NOT NULL OR p->>'assistantId' IS NOT NULL
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.v2_assistant_id',true),'') IS NOT NULL
  OR current_setting('app.system_bypass',true)='true'
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.knowledge_entries'::regclass WHERE r.rolname=session_user
   AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
 -- No caller-selected ceilings and no assistant/attended identity. Current
 -- membership remains independently enforced by every canonical native reader.
 FOR setting IN SELECT * FROM jsonb_each_text(jsonb_build_object(
  'app.agent_workspace_id',w::text,'app.agent_actor_id',actor::text,'app.agent_clearance',s.binding_sensitivity,
  'app.agent_compartments',to_jsonb(s.binding_compartments)::text,'app.agent_project_ids',to_jsonb(s.binding_project_ids)::text,
  'app.agent_mutation_compartments',to_jsonb(s.binding_compartments)::text,
  'app.agent_shared_audience','true','app.agent_visibility_assistants','[]')) LOOP
  saved:=saved||jsonb_build_object(setting.key,current_setting(setting.key,true));
  PERFORM set_config(setting.key,setting.value,true);
 END LOOP;
 IF sensitivity_rank(p->>'sensitivity')<sensitivity_rank(old.sensitivity)
  OR NOT(p->'compartments')@>to_jsonb(old.compartments) OR NOT(p->'projectIds')@>to_jsonb(old.project_ids)
  OR member_operation_scope_allows(w,p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),true) IS NOT TRUE
  OR agent_mutation_scope_allows(ARRAY(SELECT jsonb_array_elements_text(p->'compartments'))) IS NOT TRUE
  OR agent_read_scope_allows(p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid)) IS NOT TRUE
  OR native_knowledge_version_fields_allowed(w,old.id,application_knowledge_field_keys()) IS NOT TRUE
  THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
 -- Walk exact immutable observations. Unsupported kinds and all external
 -- dependencies hold before capture/archive or changing the mutable head.
 FOR node IN SELECT * FROM application_scope_lineage(w,ARRAY['knowledge_entry'],ARRAY[old.id],ARRAY[old.scope_version::text]) LOOP
  IF node.kind NOT IN('knowledge_entry','knowledge_entry_revision','knowledge_source','application_field','application_query_domain')
   THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
  IF node.kind='application_field' THEN
   current:=read_admitted_application_field_snapshot(w,node.id,node.version);
  ELSIF node.kind='application_query_domain' THEN
   -- A query domain is admitted through its complete recorded field observation.
   IF NOT EXISTS(SELECT 1 FROM application_field_resources f JOIN application_field_observations o
    ON o.workspace_id=f.workspace_id AND o.resource_id=f.id
    WHERE f.workspace_id=w AND f.resource_id=node.id AND f.selection='query_domain'
     AND EXISTS(SELECT 1 FROM application_scope_lineage(w,ARRAY['knowledge_entry'],ARRAY[old.id],ARRAY[old.scope_version::text]) l
      WHERE l.kind='application_field' AND l.id=f.id AND l.version=o.version)) THEN
    RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
   CONTINUE;
  ELSIF node.kind='knowledge_entry' THEN
   current:=read_entity_derivation_source(w,node.kind,node.id);
   IF current->>'version' IS DISTINCT FROM node.version THEN
    current:=knowledge_version_field_state(w,node.id,node.version,'{}');
    IF current IS NULL OR current->>'recordVersion' IS DISTINCT FROM node.version THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
    CONTINUE;
   END IF;
  ELSE current:=read_entity_derivation_source(w,node.kind,node.id);END IF;
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM node.version
   THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,ARRAY['knowledge_entry'],ARRAY[old.id],ARRAY[old.scope_version::text]))
  OR application_canonical_ancestry_allowed(w,'knowledge_entry',old.id,old.scope_version::text,true) IS NOT TRUE
  THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
 context:=application_knowledge_query_context(w);
 IF context IS NULL THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 fields:=CASE WHEN p->>'operation'='related' THEN ARRAY['relatedIds'] ELSE ARRAY['content','title','summary','tags','metadata'] END;
 IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
  catalog:=read_native_application_field_catalog(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry');
  mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',old.id::text,old.scope_version::text);
  FOREACH field IN ARRAY fields LOOP
   IF catalog IS NULL OR mask IS NULL OR NOT coalesce(catalog->'writeFields' ? field,false)
    OR NOT coalesce(mask->'writeFields' ? field,false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
  END LOOP;
 END IF;
 IF p->>'operation'='related' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'relatedIds') r(id) WHERE NOT EXISTS(
  SELECT 1 FROM knowledge_entries k WHERE k.id=r.id::uuid AND k.workspace_id=w AND NOT k.scope_held
   AND sensitivity_rank(k.sensitivity)<=sensitivity_rank(old.sensitivity) AND k.compartments<@old.compartments AND k.project_ids<@old.project_ids))
  THEN RAISE EXCEPTION 'knowledge_source_target_conflict';END IF;
 IF p->>'operation'='related' AND to_jsonb(old.related_ids)=p->'relatedIds'
  OR coalesce(p->>'operation','')='' AND (old.title,old.summary,old.content,to_jsonb(old.tags),old.sensitivity,old.sensitivity_explicit,old.metadata,old.source_sha,to_jsonb(old.compartments),to_jsonb(old.project_ids))
    IS NOT DISTINCT FROM (p->>'title',p->>'summary',p->>'content',coalesce(p->'tags','[]'),p->>'sensitivity',(p->>'sensitivityExplicit')::boolean,coalesce(p->'metadata','{}'),p->>'sourceSha',p->'compartments',p->'projectIds') THEN
  FOR setting IN SELECT * FROM jsonb_each_text(saved) LOOP PERFORM set_config(setting.key,coalesce(setting.value,''),true);END LOOP;
  RETURN NEXT old;RETURN;
 END IF;
 prior_revision:=capture_native_knowledge_version(w,old.id,old.scope_version::text,application_knowledge_field_keys());
 IF prior_revision IS NULL THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 PERFORM archive_native_knowledge_version(w,old.id,old.scope_version::text,prior_revision);
 -- A newly captured prior root must pair while its version is still current.
 -- New body publication is created only after these queued checks are complete.
 SET CONSTRAINTS knowledge_scope_revision_pair,knowledge_revision_publication_pair IMMEDIATE;
 SET CONSTRAINTS knowledge_scope_revision_pair,knowledge_revision_publication_pair DEFERRED;
 INSERT INTO knowledge_entry_scope_revisions(workspace_id,entry_id,sensitivity,compartments,project_ids,revision_kind)
  VALUES(w,old.id,p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid),'body') RETURNING id INTO next_revision;
 INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'knowledge_entry_revision',next_revision,'1','knowledge-source-reconciliation',NULL,NULL,p->>'sensitivity',
   ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid),revision
  FROM workspace_access_policies WHERE workspace_id=w RETURNING id INTO derivation;
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version) VALUES
  (w,derivation,'knowledge_entry_revision',prior_revision,'1'),(w,derivation,'knowledge_source',s.id,s.binding_version::text);
 -- Canonical field validation requires exact direct witnesses as well as the
 -- complete immutable root. Reuse original identities/versions; never observe anew.
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT DISTINCT w,derivation,'application_field',(dependency.source->>'resourceId')::uuid,dependency.node_version
  FROM read_application_field_dependencies(w,ARRAY['knowledge_entry'],ARRAY[old.id],ARRAY[old.scope_version::text]) dependency;
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies IMMEDIATE;
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies DEFERRED;
 IF p->>'operation'='related' THEN
  UPDATE knowledge_entries SET related_ids=ARRAY(SELECT jsonb_array_elements_text(p->'relatedIds')::uuid) WHERE id=old.id RETURNING * INTO output;
 ELSE
  UPDATE knowledge_entries SET title=p->>'title',summary=p->>'summary',content=p->>'content',tags=ARRAY(SELECT jsonb_array_elements_text(p->'tags')),
   sensitivity=p->>'sensitivity',sensitivity_explicit=(p->>'sensitivityExplicit')::boolean,metadata=coalesce(p->'metadata','{}'),
   source_sha=p->>'sourceSha',compartments=ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),project_ids=ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid)
   WHERE id=old.id AND scope_version=old.scope_version RETURNING * INTO output;
 END IF;
 PERFORM publish_native_knowledge_body_revision(w,old.id,output.scope_version::text,next_revision);
 INSERT INTO knowledge_repo_publication_heads VALUES(w,old.id,output.scope_version::text);
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies IMMEDIATE;
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies DEFERRED;
 FOR setting IN SELECT * FROM jsonb_each_text(saved) LOOP PERFORM set_config(setting.key,coalesce(setting.value,''),true);END LOOP;
 RETURN NEXT output;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.apply_knowledge_source_refresh(jsonb,jsonb)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_predecessor_2(jsonb,jsonb)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false),makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','apply_knowledge_source_refresh(jsonb,jsonb)';END IF;
  IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid<>actual.oid AND p.pronamespace<>pg_my_temp_schema()
   AND (strpos(p.prosrc,'e7da994df3db0909fbfd5729391915166a1957a5c5c8316d30c7b2b947f2e2af')>0 OR strpos(p.prosrc,md5(actual.prosrc))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(to_jsonb(actual)::text,'UTF8')),'hex'))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(ROW(actual.oid,actual.proname,actual.pronamespace,actual.proowner,actual.prolang,actual.procost,actual.prorows,actual.provariadic,actual.prosupport,actual.prokind,actual.prosecdef,actual.proleakproof,actual.proisstrict,actual.proretset,actual.provolatile,actual.proparallel,actual.pronargs,actual.pronargdefaults,actual.prorettype,actual.proargtypes,actual.proallargtypes,actual.proargmodes,actual.proargnames,actual.proargdefaults::text,actual.protrftypes,actual.prosrc,actual.probin,actual.prosqlbody::text,actual.proconfig,actual.proacl)::public.native_executable_contract_v1::text,'UTF8')),'hex'))>0))
   OR EXISTS(SELECT 1 FROM public.native_turn_contract_helpers WHERE signature='apply_knowledge_source_refresh(jsonb,jsonb)')
   OR EXISTS(SELECT 1 FROM public.native_retained_contract_helpers WHERE signature='apply_knowledge_source_refresh(jsonb,jsonb)')
  THEN RAISE EXCEPTION 'legacy_bypass_unreviewed_function_pin: %','apply_knowledge_source_refresh(jsonb,jsonb)';END IF;
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_predecessor_2(jsonb,jsonb);
CREATE FUNCTION pg_temp.legacy_bypass_predecessor_3(p_workspace_id uuid,p_team_id uuid) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE viewer uuid; reach text[];
BEGIN
  IF current_setting('app.system_bypass',true)='true' THEN RETURN true; END IF;
  viewer=nullif(current_setting('app.current_user_id',true),'')::uuid;
  IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=p_workspace_id AND user_id=viewer) THEN RETURN false; END IF;
  -- INSERT ... RETURNING evaluates SELECT policies before the inserted group
  -- is query-visible to a STABLE helper. Administrative authority is independent
  -- of group visibility and must not query the not-yet-visible group row.
  IF EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=p_workspace_id AND user_id=viewer AND role IN ('owner','admin')) THEN RETURN true; END IF;
  reach=effective_member_read_compartments(viewer,p_workspace_id);
  RETURN EXISTS(SELECT 1 FROM workspace_groups g WHERE g.id=p_team_id AND g.workspace_id=p_workspace_id AND (
    g.kind<>'team' OR g.directory_visibility='workspace' OR reach IS NULL OR g.compartment_key=ANY(reach)
    OR EXISTS(SELECT 1 FROM workspace_team_managers m WHERE m.workspace_id=p_workspace_id AND m.team_id=p_team_id AND m.user_id=viewer AND m.revoked_at IS NULL)
  ));
END;
$$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.can_view_department_directory(uuid,uuid)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_predecessor_3(uuid,uuid)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM NULL
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','can_view_department_directory(uuid,uuid)';END IF;
  IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid<>actual.oid AND p.pronamespace<>pg_my_temp_schema()
   AND (strpos(p.prosrc,'f13a473eef84cdcfb7cc4146e1a72c2f00b51eb39fe38dff38fb2555987cbfdc')>0 OR strpos(p.prosrc,md5(actual.prosrc))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(to_jsonb(actual)::text,'UTF8')),'hex'))>0
    OR strpos(p.prosrc,encode(sha256(convert_to(ROW(actual.oid,actual.proname,actual.pronamespace,actual.proowner,actual.prolang,actual.procost,actual.prorows,actual.provariadic,actual.prosupport,actual.prokind,actual.prosecdef,actual.proleakproof,actual.proisstrict,actual.proretset,actual.provolatile,actual.proparallel,actual.pronargs,actual.pronargdefaults,actual.prorettype,actual.proargtypes,actual.proallargtypes,actual.proargmodes,actual.proargnames,actual.proargdefaults::text,actual.protrftypes,actual.prosrc,actual.probin,actual.prosqlbody::text,actual.proconfig,actual.proacl)::public.native_executable_contract_v1::text,'UTF8')),'hex'))>0))
   OR EXISTS(SELECT 1 FROM public.native_turn_contract_helpers WHERE signature='can_view_department_directory(uuid,uuid)')
   OR EXISTS(SELECT 1 FROM public.native_retained_contract_helpers WHERE signature='can_view_department_directory(uuid,uuid)')
  THEN RAISE EXCEPTION 'legacy_bypass_unreviewed_function_pin: %','can_view_department_directory(uuid,uuid)';END IF;
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_predecessor_3(uuid,uuid);
CREATE FUNCTION pg_temp.legacy_bypass_predecessor_4(a crm_activities,mutation boolean) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
  SELECT NOT a.scope_held
    AND (a.scope_origin='captured' OR NOT EXISTS(SELECT 1 FROM workspace_access_policies p
      WHERE p.workspace_id=a.workspace_id AND p.classification_mode='strict'))
    AND CASE WHEN current_setting('app.system_bypass',true)='true' THEN true ELSE EXISTS(
      SELECT 1 FROM entities e JOIN workspaces w ON w.id=e.workspace_id JOIN workspace_members m ON m.workspace_id=e.workspace_id
        AND m.user_id=nullif(current_setting('app.current_user_id',true),'')::uuid
      WHERE e.id=a.entity_id AND e.workspace_id=a.workspace_id
        AND e.kind IN('person','company','deal') AND e.valid_to IS NULL AND e.retracted_at IS NULL AND NOT e.scope_held
        AND (a.user_id IS NULL OR a.user_id=m.user_id) AND (e.user_id IS NULL OR e.user_id=m.user_id)
        AND CASE WHEN w.department_read_v2 THEN
          department_read_grants() ? a.workspace_id::text
          AND department_row_allows(department_read_grants(),a.workspace_id,a.sensitivity,a.compartments,a.user_id)
          AND department_row_allows(department_read_grants(),e.workspace_id,e.sensitivity,e.compartments,e.user_id)
        ELSE (sensitivity_rank(a.sensitivity)<=sensitivity_rank(m.clearance)
        AND sensitivity_rank(e.sensitivity)<=sensitivity_rank(m.clearance)
        AND (effective_member_team_compartments(m.user_id,m.workspace_id) IS NULL OR
          (a.compartments <@ effective_member_team_compartments(m.user_id,m.workspace_id)
            AND e.compartments <@ effective_member_team_compartments(m.user_id,m.workspace_id)))
        AND context_scope_allows_current_principal(a.workspace_id,a.sensitivity,a.compartments,a.project_ids)
        AND context_scope_allows_current_principal(e.workspace_id,e.sensitivity,e.compartments,e.project_ids)) END
        AND agent_visibility_allows(a.workspace_id,a.user_id,a.assistant_id)
        AND agent_visibility_allows(e.workspace_id,e.user_id,e.assistant_id)
        AND (NOT mutation OR (agent_mutation_scope_allows(a.compartments) AND agent_mutation_scope_allows(e.compartments)))
    ) END
$$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.crm_activity_scope_allows(crm_activities,boolean)');
